sp_InserirHistoricoStatus	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_InserirHistoricoStatus`(\n\n    IN p_idPedido        INT,\n\n    IN p_statusPedido_id INT,\n\n    IN p_idUsuario       INT,\n\n    IN p_observacao      VARCHAR(300)\n\n)\nBEGIN\n\n    INSERT INTO PedidoStatusHistorico (idPedido, statusPedido_id, idUsuario, dthAlteracao, observacao)\n\n    VALUES (p_idPedido, p_statusPedido_id, p_idUsuario, NOW(), p_observacao);\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
